#!/usr/bin/env python3
# This script is generated by AI
"""interop_test.py - IEEE 802.15.4 interop test on the radio-hil

Builds examples/networking/gnrc/networking for every radio in radios.yaml,
flashes the boards with radio-hil and lets every pair of radios ping each
other in both directions, first unfragmented, then (only if that passed)
fragmented. Pairs on different channels and bands run at the same time.

Examples:
    interop_test.py --riotbase ~/RIOT --dry-run
    interop_test.py --riotbase ~/RIOT --count 100 --radios nrf52840dk samr21-xpro
    interop_test.py --riotbase ~/RIOT --pings short
    interop_test.py --riotbase ~/RIOT --dut nrf52840dk
    interop_test.py --riotbase ~/RIOT --resume interop-results/20261019-120000-1a2b3c4

See README.md next to this script.
"""
import argparse
import datetime
import itertools
import json
import os
import re
import subprocess
import sys
import threading
import time

try:
    import yaml
except ImportError:
    sys.exit("pyyaml is missing: pip install -r tests/interop/requirements.txt")

HERE = os.path.dirname(os.path.abspath(__file__))
APP = "examples/networking/gnrc/networking"
MODULES = "shell_cmd_gnrc_pktbuf"          # 'pktbuf' shell command
RADIO_HIL = os.environ.get("RADIO_HIL", "radio-hil")
BOARDS_CACHE = os.path.expanduser("~/.cache/radio-hil/boards.json")
BOOT_WAIT = float(os.environ.get("INTEROP_BOOT_WAIT", 5))   # s after poweron until the USB serial is there
SHELL_TIMEOUT = 10    # seconds for ordinary shell commands
BAND_CHANNELS = {"2.4ghz": range(11, 27), "subghz": range(0, 11)}

PRINT_LOCK = threading.Lock()


def log(msg):
    with PRINT_LOCK:
        print(f"[{datetime.datetime.now():%H:%M:%S}] {msg}", flush=True)


def die(msg):
    sys.exit(f"Error: {msg}")


def natural(name):
    """Sort key: nrf52840dk-2 before nrf52840dk-10."""
    return [int(t) if t.isdigit() else t for t in re.split(r"(\d+)", name)]


# --- radio file and plan ----------------------------------------------------

def load_config(path):
    with open(path) as fh:
        cfg = yaml.safe_load(fh)
    for key in ("radios", "phys", "test"):
        if key not in cfg:
            die(f"{path}: '{key}' missing")
    for name, radio in cfg["radios"].items():
        if "board" not in radio or not radio.get("phys"):
            die(f"{path}: radio '{name}' needs 'board' and 'phys'")
        for phy in radio["phys"]:
            if phy not in cfg["phys"]:
                die(f"{path}: radio '{name}' has unknown phy '{phy}'")
        radio.setdefault("make", {})
    for name, phy in cfg["phys"].items():
        if phy.get("band") not in BAND_CHANNELS or not phy.get("channels"):
            die(f"{path}: phy '{name}' needs band ({'/'.join(BAND_CHANNELS)}) and channels")
    cfg["exclude"] = {frozenset(pair) for pair in cfg.get("exclude") or []}
    # test.pings: list of ping runs, in this order -> {name: settings}
    pings = cfg["test"].get("pings") or []
    if not pings:
        die(f"{path}: 'test.pings' is empty")
    cfg["test"]["phases"] = {}
    for n, ping in enumerate(pings, start=1):
        ping = dict(ping)
        name = str(ping.pop("name", f"ping{n}"))
        missing = [k for k in ("size", "count", "interval") if k not in ping]
        if missing:
            die(f"{path}: ping '{name}' needs {', '.join(missing)}")
        if name in cfg["test"]["phases"]:
            die(f"{path}: ping name '{name}' used twice")
        cfg["test"]["phases"][name] = ping
    return cfg


def load_exemplars(cfg):
    """{radio: [board names in the HIL]}, from 'radio-hil fetch'."""
    with open(BOARDS_CACHE) as fh:
        boards = json.load(fh)
    by_board = {}
    for name, entry in boards.items():
        by_board.setdefault(entry["board"], []).append(name)
    return {radio: sorted(by_board.get(r["board"], []), key=natural)
            for radio, r in cfg["radios"].items()}


def plan_jobs(cfg, exemplars, radios, dut):
    """One job per direction: {'id', 'src', 'dst', 'phy', 'band'}."""
    jobs = []
    for x, y in itertools.combinations_with_replacement(radios, 2):
        if dut and dut not in (x, y):
            continue
        if frozenset((x, y)) in cfg["exclude"]:
            continue
        common = [p for p in cfg["radios"][x]["phys"] if p in cfg["radios"][y]["phys"]]
        if not common:
            continue
        # both radios need their own board; same board type -> two exemplars
        same_board = cfg["radios"][x]["board"] == cfg["radios"][y]["board"]
        need = 2 if same_board else 1
        if len(exemplars[x]) < need or len(exemplars[y]) < need:
            if x == y and len(exemplars[x]) == 1:
                continue                      # one exemplar: no test against itself
            log(f"skipping {x} <-> {y}: not enough boards in the HIL")
            continue
        phy = common[0]
        band = cfg["phys"][phy]["band"]
        # against itself one direction is enough, both ends are the same radio
        directions = ((x, y),) if x == y else ((x, y), (y, x))
        for n, (src, dst) in enumerate(directions, start=1):
            jobs.append({"id": f"{x}~{y}~{n}", "src": src, "dst": dst,
                         "phy": phy, "band": band})
    return jobs


# --- building and flashing --------------------------------------------------

def git_commit(riotbase):
    def git(*args):
        return subprocess.run(["git", "-C", riotbase, *args], capture_output=True, text=True)
    res = git("rev-parse", "--short", "HEAD")
    if res.returncode != 0:
        return "unknown"
    commit = res.stdout.strip()
    if git("diff", "--quiet", "HEAD").returncode != 0:
        commit += "-dirty"
    return commit


def build_env(radio_cfg, board, bindir):
    env = os.environ.copy()
    env.update(BOARD=board, BINDIR=bindir)
    make = dict(radio_cfg["make"])
    usemodule = make.pop("USEMODULE", "")
    if isinstance(usemodule, list):
        usemodule = " ".join(usemodule)
    env["USEMODULE"] = f"{MODULES} {usemodule}".strip()
    for key, value in make.items():
        env[key] = " ".join(map(str, value)) if isinstance(value, list) else str(value)
    return env


def build(cfg, radio, riotbase, commit, logdir):
    """Build the app for radio, returns the file to flash."""
    r = cfg["radios"][radio]
    app = os.path.join(riotbase, APP)
    bindir = os.path.join(riotbase, "build", "interop", commit, radio)
    env = build_env(r, r["board"], bindir)
    logfile = os.path.join(logdir, f"build-{radio}.log")
    log(f"building {radio} ({r['board']}) -> {bindir}")
    with open(logfile, "w") as fh:
        res = subprocess.run(["make", f"-j{os.cpu_count() or 1}", "-C", app, "all"],
                             env=env, stdout=fh, stderr=subprocess.STDOUT)
    if res.returncode != 0:
        die(f"build of {radio} failed, see {logfile}")
    res = subprocess.run(["make", "-s", "--no-print-directory", "-C", app,
                          "info-debug-variable-FLASHFILE"],
                         env=env, capture_output=True, text=True)
    lines = res.stdout.strip().splitlines()
    firmware = lines[-1] if lines else ""
    if res.returncode != 0 or not os.path.isfile(firmware):
        die(f"no flash file for {radio}: '{firmware}' {res.stderr}")
    return firmware


def radio_hil(*args, logfile=None, check=True):
    """Run radio-hil, output into logfile (or captured), returns success."""
    cmd = [RADIO_HIL, *args]
    if logfile:
        with open(logfile, "a") as fh:
            fh.write(f"$ {' '.join(cmd)}\n")
            fh.flush()
            res = subprocess.run(cmd, stdout=fh, stderr=subprocess.STDOUT)
    else:
        res = subprocess.run(cmd, capture_output=True, text=True)
    if res.returncode != 0 and check:
        detail = f", see {logfile}" if logfile else f": {res.stdout}{res.stderr}"
        log(f"radio-hil {' '.join(args)} failed{detail}")
    return res.returncode == 0


# --- shells -----------------------------------------------------------------

def shell_classes():
    """riotctrl classes; imported late so --dry-run works without them."""
    from riotctrl.ctrl import RIOTCtrl
    from riotctrl_shell.gnrc import GNRCICMPv6Echo, GNRCPktbufStats
    from riotctrl_shell.netif import Ifconfig

    class HilCtrl(RIOTCtrl):
        """RIOTCtrl whose terminal is 'radio-hil serial <name>'."""
        def __init__(self, name):
            super().__init__(env={"BOARD": name})
            self.name = name

        def make_command(self, targets):
            if tuple(targets) == self.TERM_TARGETS:
                return [RADIO_HIL, "serial", self.name]
            if tuple(targets) == self.RESET_TARGETS:
                return [RADIO_HIL, "reset", "-b", self.name]
            raise ValueError(f"unsupported targets {targets}")

    class Shell(Ifconfig, GNRCICMPv6Echo, GNRCPktbufStats):
        pass

    return HilCtrl, Shell


class Hang(Exception):
    """A shell did not answer."""


class Node:
    """One board in a run: its shell, netif and link-local address."""

    def __init__(self, name, logfile):
        HilCtrl, Shell = shell_classes()
        self.name = name
        self.ctrl = HilCtrl(name)
        self.shell = Shell(self.ctrl)
        self.logfile = open(logfile, "a")
        self.netif = self.addr = None

    def start(self):
        self.ctrl.start_term()
        self.ctrl.term.logfile_read = self.logfile

    def stop(self):
        try:
            self.ctrl.stop_term()
        finally:
            self.logfile.close()

    def cmd(self, line, timeout=SHELL_TIMEOUT):
        import pexpect
        try:
            return self.shell.cmd(line, timeout=timeout)
        except pexpect.TIMEOUT:
            raise Hang(f"{self.name}: no answer to '{line}'") from None
        except pexpect.EOF:
            raise Hang(f"{self.name}: serial connection closed") from None

    def setup(self, band, channel):
        """Find the 802.15.4 interface of the band, set the channel."""
        from riotctrl_shell.netif import IfconfigListParser
        netifs = IfconfigListParser().parse(self.cmd("ifconfig"))
        for netif, info in netifs.items():
            if "long_hwaddr" not in info or info.get("channel") not in BAND_CHANNELS[band]:
                continue
            addrs = [a["addr"] for a in info.get("ipv6_addrs", []) if a.get("scope") == "link"]
            if addrs:
                self.netif, self.addr = netif, addrs[0]
                break
        else:
            raise RuntimeError(f"{self.name}: no {band} 802.15.4 interface in 'ifconfig'")
        res = self.cmd(f"ifconfig {self.netif} set channel {channel}")
        if "success" not in res:
            raise RuntimeError(f"{self.name}: setting channel {channel} failed: {res.strip()}")

    def pktbuf_empty(self):
        from riotctrl_shell.gnrc import GNRCPktbufStatsParser
        return GNRCPktbufStatsParser().parse(self.cmd("pktbuf")).is_empty()


def ping(pinger, pinged, phase, test):
    """Ping phase; returns the measured values (raises Hang)."""
    from riotctrl_shell.gnrc import GNRCICMPv6EchoParser
    count, interval, size = phase["count"], phase["interval"], phase["size"]
    wait = phase.get("timeout", test.get("ping_timeout", 1000))
    line = (f"ping {pinged.addr}%{pinger.netif} -c {count} -i {interval} "
            f"-s {size} -W {wait}")
    # all pings plus 50 % reserve and a minute, then it counts as hang
    timeout = count * interval / 1000 * 1.5 + wait / 1000 + 60
    res = GNRCICMPv6EchoParser().parse(pinger.cmd(line, timeout=timeout))
    if "stats" not in res:
        raise RuntimeError(f"{pinger.name}: no ping statistics")
    stats = res["stats"]
    tx, rx = stats.get("tx", 0), stats.get("rx", 0)
    loss = 100.0 * (tx - rx) / tx if tx else 100.0
    return {"tx": tx, "rx": rx, "dup": stats.get("dup", 0), "loss": round(loss, 2),
            "rtt": res.get("rtts", {})}


# --- runner -----------------------------------------------------------------

class Runner:
    def __init__(self, cfg, args, jobs, exemplars, firmware, outdir):
        self.cfg, self.args, self.jobs = cfg, args, jobs
        self.exemplars = exemplars
        self.firmware = firmware          # {radio: flash file}
        self.outdir = outdir
        self.flashed = {}                 # {board name: radio}
        self.cv = threading.Condition()
        self.busy = set()                 # board names in use
        self.free = {band: list(dict.fromkeys(
            ch for phy in cfg["phys"].values() if phy["band"] == band
            for ch in phy["channels"])) for band in BAND_CHANNELS}
        self.running = 0
        self.power_lock = threading.Lock()
        self.results_lock = threading.Lock()
        self.nodes = set()                # open shells, closed on Ctrl-C
        self.counter = itertools.count(1)
        self.max_parallel = 1 if args.no_parallel else len(jobs) or 1
        self.aborted = False              # Ctrl-C: record nothing more

    # firmware state survives --resume --skip-flash
    def save_flashed(self):
        with open(os.path.join(self.outdir, "flashed.json"), "w") as fh:
            json.dump(self.flashed, fh, indent=2, sort_keys=True)

    def record(self, result):
        with self.results_lock:
            if self.aborted:
                return
            with open(os.path.join(self.outdir, "results.jsonl"), "a") as fh:
                fh.write(json.dumps(result) + "\n")

    def power(self, action, names):
        with self.power_lock:         # uhubctl runs better one at a time
            return radio_hil(action, "-b", *names)

    # --- initial flash ---

    def flash(self, name, radio, logfile):
        """Flash one board (it must be on); on failure power cycle it and try
        once more (e.g. 'No available nodes' while USB is still enumerating)."""
        for attempt in (1, 2):
            if radio_hil("flash", "-b", name, "-f", self.firmware[radio],
                         logfile=logfile, check=False):
                self.flashed[name] = radio
                self.save_flashed()
                return True
            if attempt == 1:
                log(f"flashing {name} failed, power cycling it and trying again")
                with self.power_lock:
                    radio_hil("reset", "-b", name, logfile=logfile, check=False)
                time.sleep(max(BOOT_WAIT, 5))
        self.flashed.pop(name, None)      # unknown state, flashed again when used
        self.save_flashed()
        log(f"flashing {name} failed, see {logfile}")
        return False

    def initial_flash(self):
        """Flash every board with the first radio of its board type."""
        jobs = {}                             # {board name: radio}
        for radio, names in self.exemplars.items():   # radios.yaml order
            for name in names:
                if name not in jobs and radio in self.firmware:
                    jobs[name] = radio
        if not jobs:
            return
        logdir = os.path.join(self.outdir, "logs")
        log(f"power on {len(jobs)} boards and flash them")
        self.power("poweron", list(jobs))
        time.sleep(max(BOOT_WAIT, 10))      # many boards enumerate at once
        threads = [threading.Thread(target=self.flash, daemon=True,
                                    args=(name, radio, os.path.join(logdir, f"flash-{name}.log")))
                   for name, radio in jobs.items()]
        for t in threads:
            t.start()
        for t in threads:
            while t.is_alive():               # join() with timeout: Ctrl-C works
                t.join(0.5)
        failed = sorted(n for n in jobs if self.flashed.get(n) != jobs[n])
        if failed:
            log(f"not flashed: {', '.join(failed)} (tried again when a run needs them)")
            log("'No available nodes!' in a flash log: the board is locked "
                "(ls /tmp/inet_nm/locks on its Pi) or not seen on USB (dmesg on its Pi)")

    # --- scheduling ---

    def pick(self, job):
        """Free boards and channel for job, or None. Called with self.cv held."""
        channels = self.free[job["band"]]
        if not channels:
            return None
        # prefer boards that already have the right firmware
        def candidates(radio, taken):
            names = [n for n in self.exemplars[radio] if n not in self.busy and n not in taken]
            names.sort(key=natural)
            return sorted(names, key=lambda n: self.flashed.get(n) != radio)  # stable
        src = candidates(job["src"], ())
        if not src:
            return None
        dst = candidates(job["dst"], (src[0],))
        if not dst:
            # src[0] may be the only free board of the other radio, try the rest
            for s in src[1:]:
                dst = candidates(job["dst"], (s,))
                if dst:
                    src = [s]
                    break
            else:
                return None
        return src[0], dst[0], channels[0]

    def run(self, pending):
        with self.cv:
            while pending or self.running:
                for job in list(pending):
                    if self.running >= self.max_parallel:
                        break
                    picked = self.pick(job)
                    if not picked:
                        continue
                    src, dst, channel = picked
                    pending.remove(job)
                    self.busy.update((src, dst))
                    self.free[job["band"]].remove(channel)
                    self.running += 1
                    threading.Thread(target=self.worker, daemon=True,
                                     args=(job, src, dst, channel)).start()
                if not pending and not self.running:
                    break
                if not self.running:          # nothing runs and nothing can start
                    for job in pending:
                        log(f"cannot run {job['id']}: no free boards")
                    break
                self.cv.wait()

    def worker(self, job, src, dst, channel):
        try:
            self.run_job(job, src, dst, channel)
        except Exception as exc:              # keep the other runs going
            if not self.aborted:
                log(f"{job['id']}: unexpected error: {exc!r}")
        finally:
            with self.cv:
                self.busy.difference_update((src, dst))
                self.free[job["band"]].append(channel)
                self.free[job["band"]].sort()
                self.running -= 1
                self.cv.notify_all()

    # --- one direction ---

    def run_job(self, job, src, dst, channel):
        n = next(self.counter)
        tag = f"{src} ({job['src']}) -> {dst} ({job['dst']}) ch {channel}"
        base = {"job": job["id"], "src_radio": job["src"], "dst_radio": job["dst"],
                "src": src, "dst": dst, "band": job["band"], "phy": job["phy"],
                "channel": channel, "commit": self.args.commit}
        logdir = os.path.join(self.outdir, "logs")
        prefix = os.path.join(logdir, f"{n:03d}-{src}-to-{dst}")
        log(f"start  {tag}")
        phases = list(self.cfg["test"]["phases"].items())
        done = set()

        def finish(phase, result, **values):
            done.add(phase)
            rec = dict(base, phase=phase, result=result, **values,
                       time=datetime.datetime.now().isoformat(timespec="seconds"))
            self.record(rec)
            if self.aborted:
                return
            extra = f" loss {values['loss']} %" if "loss" in values else ""
            reason = f" ({values['error']})" if "error" in values else ""
            log(f"{result:7} {tag} {phase}{extra}{reason}")

        def skip_rest(reason, first="skipped"):
            """Record the ping runs not done yet; the first one as 'first'."""
            for phase, _ in phases:
                if phase not in done:
                    finish(phase, first, error=reason)
                    first = "skipped"
                    reason = "previous ping did not pass"

        if not self.power("poweron", (src, dst)):
            skip_rest("poweron failed", first="error")
            self.power("poweroff", (src, dst))
            return
        nodes = []
        try:
            time.sleep(BOOT_WAIT)
            for name, radio in ((src, job["src"]), (dst, job["dst"])):
                if self.flashed.get(name) != radio:
                    log(f"flash  {name} with {radio}")
                    if not self.flash(name, radio, f"{prefix}-flash.log"):
                        raise RuntimeError(f"flashing {name} failed")
            pinger = Node(src, f"{prefix}-{src}.log")
            pinged = Node(dst, f"{prefix}-{dst}.log")
            nodes = [pinger, pinged]
            for node in nodes:
                with self.cv:
                    self.nodes.add(node)
                node.start()
            for node in nodes:
                node.setup(job["band"], channel)
        except Exception as exc:          # Hang, RuntimeError, no riotctrl, ...
            skip_rest(str(exc) or repr(exc), first="error")
            self.close(nodes, src, dst)
            return

        test = self.cfg["test"]
        try:
            for phase, params in phases:
                params = dict(params)
                if self.args.count:
                    params["count"] = self.args.count
                start = time.monotonic()
                try:
                    values = ping(pinger, pinged, params, test)
                    time.sleep(test.get("pktbuf_wait", 10))
                    empty = {node.name: node.pktbuf_empty() for node in nodes}
                except Hang as exc:
                    finish(phase, "hang", error=str(exc), duration=round(time.monotonic() - start))
                    break
                except RuntimeError as exc:
                    finish(phase, "error", error=str(exc), duration=round(time.monotonic() - start))
                    break
                max_loss = params.get("max_loss", test.get("max_loss", 10))
                ok = values["loss"] < max_loss and all(empty.values())
                finish(phase, "passed" if ok else "failed", **values,
                       pktbuf_empty=empty, duration=round(time.monotonic() - start),
                       size=params["size"], count=params["count"],
                       interval=params["interval"])
                if not ok and test.get("stop_on_fail", True):
                    break
            skip_rest("previous ping did not pass")
        finally:
            # no retries: the boards are switched off after every run, which
            # also resets them for the next one
            self.close(nodes, src, dst)

    def close(self, nodes, src, dst):
        for node in nodes:
            try:
                node.stop()
            except Exception as exc:
                log(f"closing the shell of {node.name}: {exc!r}")
            with self.cv:
                self.nodes.discard(node)
        self.power("poweroff", (src, dst))

    def abort(self):
        with self.results_lock:
            self.aborted = True
        with self.cv:
            nodes = list(self.nodes)
        for node in nodes:
            try:
                node.ctrl.stop_term()
            except Exception:
                pass
        radio_hil("poweroff", "-a", check=False)


# --- report -----------------------------------------------------------------

def load_results(outdir):
    """Latest result per (job, phase)."""
    results = {}
    path = os.path.join(outdir, "results.jsonl")
    if os.path.exists(path):
        with open(path) as fh:
            for line in fh:
                if line.strip():
                    r = json.loads(line)
                    results[(r["job"], r["phase"])] = r
    return results


def write_summary(outdir, jobs, cfg):
    results = load_results(outdir)
    phases = list(cfg["test"]["phases"])
    rows, counts = [], {}
    for job in jobs:
        for phase in phases:
            r = results.get((job["id"], phase))
            if not r:
                continue
            counts[r["result"]] = counts.get(r["result"], 0) + 1
            rtt = r.get("rtt", {})
            rtt_txt = (f"{rtt['min']:.1f}/{rtt['avg']:.1f}/{rtt['max']:.1f}"
                       if {"min", "avg", "max"} <= set(rtt) else "")
            pktbuf = r.get("pktbuf_empty")
            pktbuf_txt = "" if pktbuf is None else (
                "empty" if all(pktbuf.values()) else
                "not empty: " + ", ".join(n for n, e in pktbuf.items() if not e))
            loss = f"{r['loss']}" if "loss" in r else ""
            note = r.get("error", "")
            rows.append(f"| {r['src_radio']} ({r['src']}) | {r['dst_radio']} ({r['dst']}) "
                        f"| {r['band']} | {r['channel']} | {phase} | **{r['result']}** "
                        f"| {loss} | {r.get('rx', '')}/{r.get('tx', '')} | {rtt_txt} "
                        f"| {pktbuf_txt} | {r.get('duration', '')} | {note} |")
    commit = next((r["commit"] for r in results.values()), "")
    lines = [f"# Interop test {os.path.basename(outdir)}", "",
             f"RIOT commit: `{commit}`", "",
             "Result: " + ", ".join(f"{v} {k}" for k, v in sorted(counts.items())), "",
             "| Sender | Receiver | Band | Channel | Ping | Result | Loss % | rx/tx "
             "| RTT min/avg/max ms | pktbuf | Duration s | Note |",
             "|---|---|---|---|---|---|---|---|---|---|---|---|", *rows, ""]
    with open(os.path.join(outdir, "summary.md"), "w") as fh:
        fh.write("\n".join(lines))
    return counts


# --- main -------------------------------------------------------------------

def main():
    p = argparse.ArgumentParser(description=__doc__,
                                formatter_class=argparse.RawDescriptionHelpFormatter)
    p.add_argument("--radios-file", default=os.path.join(HERE, "radios.yaml"))
    p.add_argument("--riotbase", default=os.getcwd(),
                   help="RIOT checkout to build from (default: current folder)")
    p.add_argument("--dut", metavar="RADIO", help="only pairs with this radio")
    p.add_argument("--radios", nargs="+", metavar="RADIO", help="only these radios")
    p.add_argument("--pings", nargs="+", metavar="NAME",
                   help="only these ping runs of radios.yaml (e.g. --pings short)")
    p.add_argument("--count", type=int, help="pings per run (instead of radios.yaml)")
    p.add_argument("--no-parallel", action="store_true", help="one run at a time")
    p.add_argument("--results", default="interop-results",
                   help="folder for the result folders (default: interop-results)")
    p.add_argument("--resume", metavar="DIR", help="continue an aborted test in DIR")
    p.add_argument("--skip-build", action="store_true",
                   help="use the firmware of an earlier build of the same RIOT commit")
    p.add_argument("--skip-flash", action="store_true",
                   help="no initial flash (the boards already have the firmware)")
    p.add_argument("--dry-run", action="store_true", help="only show the plan")
    args = p.parse_args()

    cfg = load_config(args.radios_file)
    if args.pings:
        known = cfg["test"]["phases"]
        unknown = [n for n in args.pings if n not in known]
        if unknown:
            die(f"unknown ping run {', '.join(unknown)} (known: {', '.join(known)})")
        cfg["test"]["phases"] = {n: v for n, v in known.items() if n in args.pings}
    riotbase = os.path.abspath(os.path.expanduser(args.riotbase))
    if not os.path.isdir(os.path.join(riotbase, APP)):
        die(f"{riotbase} is not a RIOT checkout ({APP} missing), use --riotbase")
    sys.path.insert(0, os.path.join(riotbase, "dist", "pythonlibs"))   # riotctrl_shell
    args.commit = git_commit(riotbase)

    radios = list(cfg["radios"])
    for name in (args.radios or []) + ([args.dut] if args.dut else []):
        if name not in cfg["radios"]:
            die(f"unknown radio '{name}' (known: {', '.join(radios)})")
    if args.radios:
        radios = [r for r in radios if r in args.radios or r == args.dut]

    if not radio_hil("fetch"):
        die("radio-hil fetch failed")
    exemplars = load_exemplars(cfg)
    for radio in radios:
        if not exemplars[radio]:
            log(f"{radio}: no {cfg['radios'][radio]['board']} in the HIL, skipped")
    radios = [r for r in radios if exemplars[r]]
    exemplars = {r: exemplars[r] for r in radios}
    jobs = plan_jobs(cfg, exemplars, radios, args.dut)
    if not jobs:
        die("no pairs to test")

    phases = cfg["test"]["phases"]
    minutes = sum((args.count or ph["count"]) * ph["interval"] for ph in phases.values()) / 60000
    print(f"RIOT {args.commit} in {riotbase}")
    for name, ph in phases.items():
        print(f"  ping {name:8} -s {ph['size']} -c {args.count or ph['count']} -i {ph['interval']}")
    pairs = len({j["id"].rsplit("~", 1)[0] for j in jobs})
    print(f"{len(jobs)} directions of {pairs} pairs, "
          f"up to {minutes:.1f} min each ({len(jobs) * minutes / 60:.1f} h one after another)")
    for radio in radios:
        print(f"  {radio:22} {', '.join(exemplars[radio])}")
    for job in jobs:
        print(f"  {job['src']:>22} -> {job['dst']:22} {job['phy']}")
    if args.dry_run:
        return
    try:
        shell_classes()
    except ImportError as exc:
        die(f"{exc.name or exc} is missing in this Python ({sys.executable}).\n"
            f"Install it with: {sys.executable} -m pip install -r {HERE}/requirements.txt\n"
            f"(riotctrl_shell comes from {riotbase}/dist/pythonlibs)")

    # result folder
    if args.resume:
        outdir = args.resume
        if not os.path.isdir(outdir):
            die(f"{outdir} not found")
    else:
        stamp = datetime.datetime.now().strftime("%Y%m%d-%H%M%S")
        outdir = os.path.join(args.results, f"{stamp}-{args.commit}")
    os.makedirs(os.path.join(outdir, "logs"), exist_ok=True)
    with open(os.path.join(outdir, "plan.json"), "w") as fh:
        json.dump({"commit": args.commit, "riotbase": riotbase, "args": sys.argv[1:],
                   "exemplars": exemplars, "jobs": jobs}, fh, indent=2)

    results = load_results(outdir)
    last = list(phases)[-1]
    pending = [j for j in jobs if (j["id"], last) not in results]
    if args.resume:
        log(f"resume: {len(jobs) - len(pending)} of {len(jobs)} directions already done")

    # build every radio that is still needed
    needed = {j["src"] for j in pending} | {j["dst"] for j in pending}
    firmware = {}
    for radio in radios:
        if radio not in needed:
            continue
        if args.skip_build:
            r = cfg["radios"][radio]
            bindir = os.path.join(riotbase, "build", "interop", args.commit, radio)
            res = subprocess.run(["make", "-s", "--no-print-directory", "-C",
                                  os.path.join(riotbase, APP), "info-debug-variable-FLASHFILE"],
                                 env=build_env(r, r["board"], bindir),
                                 capture_output=True, text=True)
            fw = (res.stdout.strip().splitlines() or [""])[-1]
            if not os.path.isfile(fw):
                die(f"--skip-build: no firmware for {radio} ({fw}), build it first")
            firmware[radio] = fw
        else:
            firmware[radio] = build(cfg, radio, riotbase, args.commit,
                                    os.path.join(outdir, "logs"))

    runner = Runner(cfg, args, jobs, {r: exemplars[r] for r in radios if r in needed},
                    firmware, outdir)
    flashed_file = os.path.join(outdir, "flashed.json")
    if args.skip_flash:                 # no initial flash
        if os.path.exists(flashed_file):
            with open(flashed_file) as fh:
                runner.flashed = json.load(fh)
        else:                       # assume each board has its first radio
            for radio, names in runner.exemplars.items():
                for name in names:
                    runner.flashed.setdefault(name, radio)
    try:
        if not args.skip_flash:
            runner.initial_flash()
        radio_hil("poweroff", "-a")
        runner.run(pending)
    except KeyboardInterrupt:
        log("aborted, switching all boards off (continue with --resume)")
        runner.abort()
        write_summary(outdir, jobs, cfg)
        sys.exit(130)

    counts = write_summary(outdir, jobs, cfg)
    log(f"done: {', '.join(f'{v} {k}' for k, v in sorted(counts.items()))}")
    log(f"report: {os.path.join(outdir, 'summary.md')}")
    sys.exit(0 if set(counts) <= {"passed"} else 1)


if __name__ == "__main__":
    main()
